    html=analyticsSection("Результати синхронізації", "Успішність та обсяг останніх запусків",[stat("Запусків",runs.length),stat("Успішні",good,`${runs.length?Math.round(good/runs.length*100):0}%`),stat("Помилки",failures),stat("Оновлено товарів",runs.reduce((s,r)=>s+Number(r.stats?.updated||0),0))],[{title:"Оновлено в останніх запусках",rows:[...runs].slice(0,8).reverse().map((r,i)=>({label:`#${runs.length-i}`,value:Number(r.stats?.updated||0)}))},{title:"Додано та пропущено",rows:[{label:"Додано",value:runs.reduce((s,r)=>s+Number(r.stats?.new||0),0)},{label:"Пропущено",value:runs.reduce((s,r)=>s+Number(r.stats?.skipped||0),0)}]}]);
