for (const pageName of ["products","orders","categories","customers","reviews","newsletter","content","activity","sync"]) {
  const renderPage = ({products:renderProducts,orders:renderOrders,categories:renderCategories,customers:renderCustomers,reviews:renderReviews,newsletter:renderNewsletter,content:renderContent,activity:renderActivity,sync:renderProductSync})[pageName];
  const wrapped = async () => { await renderPage(); await addPageAnalytics(pageName); };
  if (pageName === "products") renderProducts = wrapped;
  else if (pageName === "orders") renderOrders = wrapped;
  else if (pageName === "categories") renderCategories = wrapped;
  else if (pageName === "customers") renderCustomers = wrapped;
  else if (pageName === "reviews") renderReviews = wrapped;
  else if (pageName === "newsletter") renderNewsletter = wrapped;
  else if (pageName === "content") renderContent = wrapped;
  else if (pageName === "activity") renderActivity = wrapped;
  else renderProductSync = wrapped;
}

async function render() { document.querySelectorAll("[data-view]").forEach(a=>a.classList.toggle("active",a.dataset.view===view)); app.innerHTML="<div class='loading'>Завантажуємо дані…</div>"; try { if(view==="products")return renderProducts();if(view==="sync")return renderProductSync();if(view==="reviews")return renderReviews();if(view==="orders")return renderOrders();if(view==="categories")return renderCategories();if(view==="customers")return renderCustomers();if(view==="newsletter")return renderNewsletter();if(view==="content")return renderContent();if(view==="activity")return renderActivity();return renderDashboard(); } catch(err){app.innerHTML=`<div class="panel empty">Не вдалося завантажити дані: ${esc(err.message)}</div>`;} }
await render();
